(() => {
  const D=window.NeuroPassData, E=window.NPEngine, Store=window.NPStore;
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const fmtDate=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'}):'Not set';
  let sessionTimer=null, sessionSeconds=0, studyCtx=null, mockCtx=null, modalCleanup=null;

  const roleNames={student:'Student',coach:'Learning Coach',senior:'Senior Coach',admin:'Admin'};
  const navStudent=[['home','⌂','Home'],['study','▶','Study'],['practice','?','Practice'],['mocks','◎','Mocks'],['mistake-bank','↺','Mistake Bank'],['progress','▥','Progress'],['coach','☏','Coach'],['settings','⚙','Settings']];
  const navCoach=[['coach-dashboard','⌂','Dashboard'],['risk-queue','!','Risk Queue'],['assigned-students','◉','Students'],['coach-inbox','☏','Inbox'],['settings','⚙','Settings']];
  const navAdmin=[['admin','⌂','Overview'],['admin-content','▦','Content'],['admin-import','⇧','Import'],['admin-guarantee','✓','Guarantees'],['admin-predictive','◇','Predictive'],['admin-validation','▥','Validation'],['admin-launch','!','Launch Readiness'],['settings','⚙','Settings']];

  function route(){ return (location.hash.replace(/^#/,'').split('?')[0] || 'home'); }
  function go(r){ location.hash=r; }
  function toast(text){ const n=document.createElement('div'); n.className='toast'; n.textContent=text; $('#toastRegion').appendChild(n); setTimeout(()=>n.remove(),2800); }
  function status(label,tone='neutral'){ return `<span class="status ${tone}"><span class="dot"></span>${esc(label)}</span>`; }
  function progress(n){ return `<div class="progress"><span style="width:${E.clamp(n,0,100)}%"></span></div>`; }
  function subject(id){ return D.subjects.find(x=>x.id===id) || {name:'Mixed',short:'Mixed',icon:'•'}; }
  function question(id){ return [...D.questions,...(Store.get().importedQuestions||[])].find(x=>x.id===id); }
  function cleanupTransient(){ if(sessionTimer){clearInterval(sessionTimer);sessionTimer=null;} if(modalCleanup){modalCleanup();modalCleanup=null;} if('speechSynthesis' in window) speechSynthesis.cancel(); }

  function applySettings(){
    const s=Store.get().user.settings || D.defaultSettings;
    document.documentElement.style.setProperty('--font-size',`${s.fontSize||16}px`);
    document.documentElement.style.setProperty('--line-height',s.lineHeight||1.55);
    document.documentElement.style.setProperty('--letter-spacing',`${s.letterSpacing||0}px`);
    document.body.classList.toggle('dyslexic',!!s.dyslexicFont);
    document.body.classList.toggle('reduce-motion',!!s.reduceMotion);
    document.body.classList.remove('theme-cream','theme-yellow','theme-blue');
    if(s.background && s.background!=='standard') document.body.classList.add(`theme-${s.background}`);
  }

  async function loadAuthenticatedUser(user){
    if(!user) return false;
    try{
      const {data:profile,error}=await window.NPSupabase.from('profiles').select('role,full_name').eq('id',user.id).single();
      if(error) throw error;
      await Store.attachRemoteUser(user.id,{preferRemote:true});
      const roleMap={student:'student',learning_coach:'coach',senior_coach:'senior',admin:'admin'};
      const appRole=roleMap[profile?.role]||'student';

      if(appRole==='student'){
        const [{data:studentProfile},{data:subjectRows},{data:settingsRow}]=await Promise.all([
          window.NPSupabase.from('student_profiles').select('*').eq('user_id',user.id).maybeSingle(),
          window.NPSupabase.from('student_subjects').select('subject_id').eq('student_id',user.id),
          window.NPSupabase.from('accommodation_settings').select('*').eq('user_id',user.id).maybeSingle()
        ]);
        const local=Store.get();
        const selectedSubjects=(subjectRows||[]).map(x=>x.subject_id);
        if(!studentProfile && local.onboardingComplete){
          const settings=local.user.settings||D.defaultSettings;
          await Promise.all([
            window.NPSupabase.from('student_profiles').upsert({user_id:user.id,exam_type:local.user.examType||'JAMB',exam_date:local.user.examDate||null,baseline_score:local.user.baselineScore||null,track_id:local.user.selectedTrackId||'rise',track_start:new Date().toISOString().slice(0,10),consistency_risk:!!local.user.consistencyRisk}),
            window.NPSupabase.from('accommodation_settings').upsert({user_id:user.id,dyslexic_font:!!settings.dyslexicFont,read_aloud:!!settings.readAloud,chunked_reading:!!settings.chunkedReading}),
            ...(local.user.subjects||[]).map(subject_id=>window.NPSupabase.from('student_subjects').upsert({student_id:user.id,subject_id},{onConflict:'student_id,subject_id'}))
          ]);
        }
        const effectiveProfile=studentProfile||(!local.onboardingComplete?null:{exam_type:local.user.examType,exam_date:local.user.examDate,track_id:local.user.selectedTrackId,track_start:new Date().toISOString().slice(0,10),baseline_score:local.user.baselineScore,consistency_risk:local.user.consistencyRisk});
        const effectiveSubjects=selectedSubjects.length?selectedSubjects:(local.user.subjects||[]);
        const trackStart=effectiveProfile?.track_start;
        const currentDay=trackStart?Math.max(1,Math.floor((Date.now()-new Date(`${trackStart}T00:00:00`).getTime())/86400000)+1):1;
        Store.patch(s=>{
          s.authenticated=true;
          s.demoMode=false;
          s.user.authUserId=user.id;
          s.user.id=user.id;
          s.user.email=user.email||s.user.email;
          s.user.name=profile?.full_name||s.user.name;
          s.user.firstName=(profile?.full_name||s.user.firstName||'Student').split(' ')[0];
          s.currentRole=appRole;
          if(effectiveProfile){
            s.onboardingComplete=true;
            s.user.examType=effectiveProfile.exam_type||s.user.examType;
            s.user.examDate=effectiveProfile.exam_date||s.user.examDate;
            s.user.selectedTrackId=effectiveProfile.track_id||s.user.selectedTrackId;
            s.user.trackStart=trackStart||s.user.trackStart;
            s.user.currentDay=currentDay;
            s.user.baselineScore=Number(effectiveProfile.baseline_score||0);
            s.user.consistencyRisk=!!effectiveProfile.consistency_risk;
          }
          if(effectiveSubjects.length) s.user.subjects=effectiveSubjects;
          if(settingsRow){
            s.user.settings.dyslexicFont=!!settingsRow.dyslexic_font;
            s.user.settings.readAloud=!!settingsRow.read_aloud;
            s.user.settings.chunkedReading=!!settingsRow.chunked_reading;
          }
        });
        await Store.syncNow();
      } else {
        Store.patch(s=>{s.authenticated=true;s.demoMode=false;s.user.authUserId=user.id;s.user.id=user.id;s.user.email=user.email||s.user.email;s.user.name=profile?.full_name||s.user.name;s.user.firstName=(profile?.full_name||s.user.firstName||'User').split(' ')[0];s.currentRole=appRole;});
      }
      return true;
    }catch(err){
      console.error(err);
      toast('Your account was found, but profile loading failed. Please try again.');
      return false;
    }
  }

  function authView(){
    cleanupTransient();
    $('#app').innerHTML=`<div class="auth-wrap">
      <section class="auth-visual"><div class="brand"><img src="/assets/icon.svg" alt=""><div>NeuroPass<small style="color:rgba(255,255,255,.75)">Exam preparation for minds that work differently</small></div></div>
      <div><h1>Study in a way your brain can actually use.</h1><p>JAMB and WAEC preparation with shorter learning loops, audio support, recovery days, spaced repetition and a plan that adapts to how you are doing.</p></div><small>Demo question data is illustrative. Licensed exam content can be imported by an administrator.</small></section>
      <section class="auth-panel"><div class="auth-box"><span class="eyebrow">Student access</span><h2>Welcome to NeuroPass</h2><p>No diagnosis is required. Choose what helps you learn.</p>
      <form id="loginForm" class="grid" style="gap:14px"><div class="field"><label>Email</label><input required type="email" name="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input required type="password" name="password" autocomplete="current-password" minlength="8"></div><button class="btn primary">Sign in</button></form>
      <div class="section-title"><p>or</p></div><button id="demoBtn" class="btn secondary" style="width:100%">Open interactive demo</button><button id="onboardBtn" class="btn ghost" style="width:100%;margin-top:8px">Create a student account</button>
      <div class="callout info" style="margin-top:18px"><strong>Private beta build</strong><p>Guarantee language remains subject to legal approval before public launch.</p></div></div></section></div>`;
    $('#loginForm').onsubmit=async e=>{
      e.preventDefault();
      if(!window.NPSupabase) return toast('Cloud sign-in is temporarily unavailable.');
      const fd=new FormData(e.target), email=String(fd.get('email')).trim(), password=String(fd.get('password'));
      const btn=e.submitter; if(btn){btn.disabled=true;btn.textContent='Signing in...';}
      const {data,error}=await window.NPSupabase.auth.signInWithPassword({email,password});
      if(btn){btn.disabled=false;btn.textContent='Sign in';}
      if(error) return toast(error.message);
      if(await loadAuthenticatedUser(data.user)){go('home');render();}
    };
    $('#demoBtn').onclick=()=>{Store.resetDemo();Store.patch(s=>{s.authenticated=true;s.demoMode=true;s.currentRole='student';});go('home');render();};
    $('#onboardBtn').onclick=()=>onboarding();
  }

  function onboarding(){
    let step=0, draft={name:'',email:'',password:'',examType:'JAMB',subjects:['english','mathematics','biology','chemistry'],track:'elite',focus:false,reading:false,audio:true,examDate:'2026-11-15'};
    const renderStep=()=>{
      const steps=[
        `<h2>Create your account</h2><p>Your progress will sync securely across devices while downloaded study packs remain available offline.</p><div class="grid" style="gap:14px;margin-top:18px"><div class="field"><label>Full name</label><input id="signupName" autocomplete="name" value="${esc(draft.name)}" placeholder="Your full name"></div><div class="field"><label>Email</label><input id="signupEmail" type="email" autocomplete="email" value="${esc(draft.email)}" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="signupPassword" type="password" autocomplete="new-password" minlength="8" value="${esc(draft.password)}" placeholder="At least 8 characters"></div></div>`,
        `<h2>What are you preparing for?</h2><p>Choose your exam. You can change subjects later.</p><div class="choice-grid" style="grid-template-columns:repeat(2,1fr);margin-top:18px"><button class="choice ${draft.examType==='JAMB'?'selected':''}" data-exam="JAMB">JAMB</button><button class="choice ${draft.examType==='WAEC'?'selected':''}" data-exam="WAEC">WAEC</button></div><div class="field" style="margin-top:16px"><label>Target exam date</label><input id="examDate" type="date" value="${draft.examDate}"></div>`,
        `<h2>Select your subjects</h2><p>For this build, the demo includes the six seeded core subjects.</p><div class="grid two" style="margin-top:16px">${D.subjects.map(x=>`<label class="check-row card flat"><input type="checkbox" data-subject="${x.id}" ${draft.subjects.includes(x.id)?'checked':''}> <strong>${x.icon} ${esc(x.name)}</strong></label>`).join('')}</div>`,
        `<h2>What usually gets in the way?</h2><p>This is not a diagnosis. It only helps NeuroPass suggest settings.</p><div class="grid" style="margin-top:16px"><label class="check-row card flat"><input id="focusBox" type="checkbox" ${draft.focus?'checked':''}><div><strong>Staying focused is difficult</strong><p>I start, drift, or abandon long study sessions.</p></div></label><label class="check-row card flat"><input id="readingBox" type="checkbox" ${draft.reading?'checked':''}><div><strong>Reading can be tiring or frustrating</strong><p>I re-read lines, lose my place, or prefer listening.</p></div></label><label class="check-row card flat"><input id="audioBox" type="checkbox" ${draft.audio?'checked':''}><div><strong>Audio helps me learn</strong><p>Suggest read-aloud support.</p></div></label></div>`,
        `<h2>Choose a commitment track</h2><p>The advertised track is not your live guarantee. Your actual guarantee changes with completed work and spaced repetition.</p><div class="track-grid" style="margin-top:16px">${D.tracks.map(t=>`<button class="track-card ${draft.track===t.id?'selected':''}" data-track="${t.id}" style="text-align:left"><div class="track-name">${t.name}</div><div class="track-score">${t.guaranteed}/400</div><small>${t.days} days, ${t.hours} hrs/day, realistic target ${t.target}</small></button>`).join('')}</div>`,
        `<h2>Your suggested setup</h2><p>Based on your answers, we have suggested these settings. Everything can be changed at any time in Settings. You decide what works for you.</p><div class="grid two" style="margin-top:16px"><div class="card flat"><strong>Focus support</strong><p>${draft.focus?'Visible timer, recovery missions and Low Energy Mode suggested.':'Standard focus settings suggested.'}</p></div><div class="card flat"><strong>Reading support</strong><p>${draft.reading?'Dyslexia-friendly font option, chunked passages and audio suggested.':'Standard typography with optional audio.'}</p></div></div><label class="check-row callout warning" style="margin-top:16px"><input id="contractAck" type="checkbox"><div><strong>Shared commitment</strong><p>I understand that guarantee eligibility depends on assigned sessions, mocks, schedule adherence and at least 80% average compliance. No track guarantees 400/400.</p></div></label>`
      ];
      $('#app').innerHTML=`<div class="auth-wrap"><section class="auth-visual"><div class="brand"><img src="/assets/icon.svg" alt=""><div>NeuroPass</div></div><div><h1 style="font-size:3.2rem">Build a plan around you.</h1><p>Short, adjustable and recoverable. No label required.</p></div><small>Step ${step+1} of ${steps.length}</small></section><section class="auth-panel"><div class="auth-box" style="width:min(680px,100%)"><div class="onboard-stepper">${steps.map((_,i)=>`<span class="${i<step?'done':i===step?'active':''}"></span>`).join('')}</div>${steps[step]}<div class="modal-actions"><button id="backStep" class="btn secondary" ${step===0?'disabled':''}>Back</button><button id="nextStep" class="btn primary">${step===steps.length-1?'Create account':'Continue'}</button></div></div></section></div>`;
      $$('[data-exam]').forEach(b=>b.onclick=()=>{draft.examType=b.dataset.exam;renderStep();});
      $$('[data-track]').forEach(b=>b.onclick=()=>{draft.track=b.dataset.track;renderStep();});
      $$('[data-subject]').forEach(b=>b.onchange=()=>{draft.subjects=$$('[data-subject]:checked').map(x=>x.dataset.subject);});
      $('#signupName')?.addEventListener('input',e=>draft.name=e.target.value);
      $('#signupEmail')?.addEventListener('input',e=>draft.email=e.target.value);
      $('#signupPassword')?.addEventListener('input',e=>draft.password=e.target.value);
      $('#examDate')?.addEventListener('change',e=>draft.examDate=e.target.value);
      $('#focusBox')?.addEventListener('change',e=>draft.focus=e.target.checked);
      $('#readingBox')?.addEventListener('change',e=>draft.reading=e.target.checked);
      $('#audioBox')?.addEventListener('change',e=>draft.audio=e.target.checked);
      $('#backStep').onclick=()=>{if(step>0){step--;renderStep();}};
      $('#nextStep').onclick=async()=>{
        if(step===0){
          if(!draft.name.trim()) return toast('Enter your full name.');
          if(!/^\S+@\S+\.\S+$/.test(draft.email)) return toast('Enter a valid email address.');
          if(draft.password.length<8) return toast('Use a password with at least 8 characters.');
        }
        if(step===2 && draft.subjects.length===0) return toast('Choose at least one subject.');
        if(step===steps.length-1){
          if(!$('#contractAck').checked) return toast('Please acknowledge the shared commitment first.');
          if(!window.NPSupabase) return toast('Cloud account creation is temporarily unavailable.');
          const btn=$('#nextStep');btn.disabled=true;btn.textContent='Creating account...';
          const {data,error}=await window.NPSupabase.auth.signUp({email:draft.email,password:draft.password,options:{emailRedirectTo:`${location.origin}/`,data:{full_name:draft.name.trim(),exam_type:draft.examType,exam_date:draft.examDate,subjects:draft.subjects,track_id:draft.track,consistency_risk:draft.focus,reading_support:draft.reading,audio_support:draft.audio}}});
          if(error){btn.disabled=false;btn.textContent='Create account';return toast(error.message);}
          if(!data.user){btn.disabled=false;btn.textContent='Create account';return toast('Account creation did not complete. Please try again.');}
          Store.reset();
          Store.patch(s=>{s.authenticated=!!data.session;s.demoMode=false;s.onboardingComplete=true;s.user.authUserId=data.user.id;s.user.id=data.user.id;s.user.email=draft.email;s.user.name=draft.name.trim();s.user.firstName=draft.name.trim().split(' ')[0];s.user.examType=draft.examType;s.user.examDate=draft.examDate;s.user.subjects=draft.subjects;s.user.selectedTrackId=draft.track;s.user.settings.dyslexicFont=draft.reading;s.user.settings.chunkedReading=draft.reading;s.user.settings.readAloud=draft.audio;s.user.consistencyRisk=draft.focus;});
          if(data.session){
            await Store.attachRemoteUser(data.user.id,{preferRemote:false});
            const settings=Store.get().user.settings;
            await Promise.all([
              window.NPSupabase.from('student_profiles').upsert({user_id:data.user.id,exam_type:draft.examType,exam_date:draft.examDate||null,baseline_score:Store.get().user.baselineScore,track_id:draft.track,track_start:new Date().toISOString().slice(0,10),consistency_risk:draft.focus}),
              window.NPSupabase.from('accommodation_settings').upsert({user_id:data.user.id,dyslexic_font:!!settings.dyslexicFont,read_aloud:!!settings.readAloud,chunked_reading:!!settings.chunkedReading}),
              ...draft.subjects.map(subject_id=>window.NPSupabase.from('student_subjects').upsert({student_id:data.user.id,subject_id},{onConflict:'student_id,subject_id'}))
            ]);
            await Store.syncNow();
            applySettings();go('home');render();
          } else {
            toast('Account created. Check your email to confirm your address, then sign in.');
            setTimeout(authView,1000);
          }
          return;
        }
        step++;renderStep();
      };
    };
    renderStep();
  }

  function shell(content, r=route()){
    const st=Store.get(), role=st.currentRole;
    const nav=role==='admin'?navAdmin:role==='student'?navStudent:navCoach;
    const navHtml=nav.map(([id,ic,label])=>`<a class="nav-link ${r===id?'active':''}" href="#${id}"><span class="nav-icon">${ic}</span>${label}</a>`).join('');
    const roleControl=st.demoMode?`<select id="roleSwitch" class="role-pill" aria-label="Demo role">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${k===role?'selected':''}>Demo: ${v}</option>`).join('')}</select>`:`<span class="role-pill">${esc(roleNames[role]||'Student')}</span>`;
    return `<header class="topbar"><a href="#${role==='admin'?'admin':role==='student'?'home':'coach-dashboard'}" class="brand"><img src="/assets/icon.svg" alt=""><div>NeuroPass<small>Exam preparation for minds that work differently</small></div></a><div class="top-actions">${roleControl}<button id="syncBtn" class="btn ghost small" title="Sync offline queue">${navigator.onLine?'Synced':'Offline'} ${st.offline.pendingSync?`(${st.offline.pendingSync})`:''}</button>${!st.demoMode?'<button id="signOutBtn" class="btn ghost small">Sign out</button>':''}<div class="avatar">${esc((role==='student'?st.user.firstName:role==='admin'?'A':'C').slice(0,1))}</div></div></header>
    <div class="layout"><aside class="sidebar"><nav class="nav-group">${navHtml}<div class="sidebar-foot"><strong>Private V1 build</strong><br>Question content is demo data until licensed source material is imported.</div></nav></aside><main class="main">${content}</main></div>
    <nav class="mobile-bottom">${nav.slice(0,4).map(([id,ic,label])=>`<a class="${r===id?'active':''}" href="#${id}"><span class="nav-icon">${ic}</span>${label}</a>`).join('')}<button id="mobileMore"><span class="nav-icon">•••</span>More</button></nav>`;
  }

  function bindShell(){
    $('#roleSwitch')?.addEventListener('change',e=>{Store.patch(s=>s.currentRole=e.target.value);const role=e.target.value;go(role==='admin'?'admin':role==='student'?'home':'coach-dashboard');render();});
    $('#syncBtn')?.addEventListener('click',async()=>{if(!navigator.onLine)return toast('Still offline. Progress is safely queued.');try{await Store.flushQueue();toast('Progress synced.');render();}catch(err){console.error(err);toast('Sync failed. Your local progress is still safe.');}});
    $('#signOutBtn')?.addEventListener('click',async()=>{try{await Store.syncNow();}catch{} await window.NPSupabase?.auth.signOut();Store.detachRemoteUser();Store.reset();go('home');render();});
    $('#mobileMore')?.addEventListener('click',()=>showModal(`<h2>More</h2><div class="grid">${(Store.get().currentRole==='student'?navStudent:Store.get().currentRole==='admin'?navAdmin:navCoach).slice(4).map(([id,ic,l])=>`<a class="btn secondary" href="#${id}" onclick="document.querySelector('.modal-backdrop')?.remove()">${ic} ${l}</a>`).join('')}</div>`));
  }

  function showModal(html, onOpen){
    closeModal(); const el=document.createElement('div'); el.className='modal-backdrop'; el.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${html}</div>`; document.body.appendChild(el); el.addEventListener('click',e=>{if(e.target===el)closeModal();}); onOpen?.(el); return el;
  }
  function closeModal(){ $('.modal-backdrop')?.remove(); if(modalCleanup){modalCleanup();modalCleanup=null;} }

  function home(){
    const s=Store.get(), track=E.getTrack(s.user.selectedTrackId), day=s.user.currentDay, daysRemain=Math.max(0,track.days-day);
    const comp=E.complianceStatus({rollingAverage:s.compliance.rollingAverage,consecutiveBelow70:s.compliance.consecutiveBelow70,daysRemaining:daysRemain});
    const next=s.today.sessions.find(x=>x.status!=='done') || s.today.sessions[0];
    const due=s.spacedQueue.filter(x=>x.status==='due').length;
    return `<div class="page"><div class="page-head"><div><span class="eyebrow">Day ${day} of ${track.days}</span><h1>Good afternoon, ${esc(s.user.firstName)}.</h1><p>Your next action is kept small on purpose. Complete the next session, then stop.</p></div>${status(navigator.onLine?'Online':'Offline',navigator.onLine?'success':'neutral')}</div>
    <section class="card hero-card"><div class="grid two"><div><span class="status" style="background:rgba(255,255,255,.14);color:white">Next session</span><h2 style="font-size:1.8rem;margin-top:12px">${esc(next.title)}</h2><p>${esc(next.meta)} · ${next.duration} minutes</p><div class="action-strip" style="margin-top:18px"><button class="btn secondary" id="startNext">Start now</button><button class="btn secondary" id="skipBtn">I cannot do this now</button></div></div><div><div class="metric-label" style="color:rgba(255,255,255,.72)">Your score projection</div><div style="font-size:3.2rem;font-weight:900;line-height:1">${s.score.projected}<span style="font-size:1rem;font-weight:700">/400</span></div><p>Current guaranteed minimum: <strong>${s.score.guaranteed}/400</strong></p><small class="muted">Model estimate, ${esc(s.score.modelVersion)}. It changes with completed work, compliance and spaced repetition.</small><button id="projectionExplain" class="btn secondary small" style="margin-top:14px">How this is calculated</button></div></div></section>
    <div class="grid four" style="margin-top:16px"><div class="metric"><div class="metric-label">Rolling compliance</div><div class="metric-value">${s.compliance.rollingAverage}%</div>${progress(s.compliance.rollingAverage)}<div class="metric-sub">${esc(comp.label)}</div></div><div class="metric"><div class="metric-label">Reviews due</div><div class="metric-value">${due}</div><div class="metric-sub">Spaced repetition runs automatically</div></div><div class="metric"><div class="metric-label">Next mock</div><div class="metric-value">${E.mockPhase(day).phase}</div><div class="metric-sub">${esc(E.mockPhase(day).cadence)}</div></div><div class="metric"><div class="metric-label">XP / level</div><div class="metric-value">${s.user.xp}</div><div class="metric-sub">Level ${s.user.level}</div></div></div>
    <div class="section-title"><h2>Today</h2><span>${s.today.sessions.filter(x=>x.status==='done').length}/${s.today.sessions.length} complete</span></div><div class="session-list">${s.today.sessions.map(x=>`<div class="session-item"><div class="session-time">${x.time}</div><div><div class="session-title">${esc(x.title)}</div><div class="session-meta">${esc(x.meta)} · ${x.duration} min</div></div>${x.status==='done'?status('Done','success'):`<button class="btn ${x.status==='next'?'primary':'secondary'} small" data-start-session="${x.id}">Start</button>`}</div>`).join('')}</div>
    <div class="grid two" style="margin-top:18px"><div class="card"><h3>Choose today’s energy</h3><p>Your schedule can shrink without becoming a skipped day.</p><div class="action-strip" style="margin-top:14px"><button class="btn soft" id="lowEnergy">Low Energy, 15 min</button><button class="btn secondary" id="powerMode">Power Mode</button></div></div><div class="card"><h3>Your guarantee status</h3><div style="margin:10px 0">${status(comp.label,comp.tone)}</div><p>${esc(comp.action)}</p><a href="#progress" class="btn ghost small" style="margin-top:8px">View compliance history</a></div></div>
    <div class="grid two" style="margin-top:18px"><div class="card"><h3>Coach support</h3><p>${s.coach.assigned.name} is your named Learning Coach. ${s.riskSignals.some(x=>x.active)?'A support signal is active.':'No urgent support signal is active.'}</p><a href="#coach" class="btn secondary small" style="margin-top:14px">Open coach</a></div><div class="card"><h3>Offline packs</h3><p>${s.offline.downloadedPacks.length} subject packs saved on this device. ${s.offline.pendingSync?`${s.offline.pendingSync} actions are waiting to sync.`:'Progress is synced.'}</p><button id="downloadPacks" class="btn secondary small" style="margin-top:14px">Manage downloads</button></div></div>
    <div class="section-title"><h2>Parent share</h2><p>Results-first, without requiring a diagnostic label</p></div><div class="callout info"><strong>Need a parent or guardian to understand the plan?</strong><p>Share your track, study commitment, current projection and how NeuroPass supports exam preparation.</p><a class="btn soft small" href="#parent-share" style="margin-top:10px">Open share page</a></div></div>`;
  }

  function bindHome(){
    $('#startNext')?.addEventListener('click',()=>startSession(Store.get().today.sessions.find(x=>x.status!=='done')?.id));
    $$('[data-start-session]').forEach(b=>b.onclick=()=>startSession(b.dataset.startSession));
    $('#skipBtn')?.addEventListener('click',skipFlow);
    $('#lowEnergy')?.addEventListener('click',()=>{Store.patch(s=>{s.today.mode='low';});toast('Low Energy Mode is ready. Your next session will be 15 minutes with familiar content.');render();});
    $('#powerMode')?.addEventListener('click',()=>{Store.patch(s=>s.today.mode='power');toast('Power Mode is on. Bonus difficulty is available, but you can stop at the normal endpoint.');render();});
    $('#projectionExplain')?.addEventListener('click',projectionModal);
    $('#downloadPacks')?.addEventListener('click',downloadModal);
  }

  function projectionModal(){
    const s=Store.get(), avg=E.avgHoursFromState(s), calc=E.projectGuarantee({daysElapsed:s.user.currentDay,avgDailyHours:avg,compliance:s.compliance.rollingAverage,mockScore:s.mockHistory.at(-1)?.score,baseline:s.user.baselineScore,selectedTrackId:s.user.selectedTrackId});
    showModal(`<span class="eyebrow">Transparent V1 model</span><h2>How your projection works</h2><p>NeuroPass does not simply display the ceiling of the track you selected.</p><div class="grid two" style="margin-top:16px"><div class="metric"><div class="metric-label">Live model guarantee</div><div class="metric-value">${calc.guaranteed}/400</div></div><div class="metric"><div class="metric-label">Model projection</div><div class="metric-value">${calc.projected}/400</div></div></div><div class="callout info" style="margin-top:16px"><strong>Current limiting factor: ${esc(calc.limitingFactor)}</strong><p>${esc(calc.explanation)}</p></div><p style="margin-top:16px">This is an explainable heuristic until NeuroPass has enough post-exam outcomes to recalibrate the model against real results.</p><div class="modal-actions"><button class="btn primary" onclick="document.querySelector('.modal-backdrop').remove()">Close</button></div>`);
  }

  function downloadModal(){
    const s=Store.get(); showModal(`<h2>Offline study packs</h2><p>Downloaded lessons and questions remain available when your connection drops.</p><div class="grid" style="margin-top:16px">${s.user.subjects.map(id=>{const sub=subject(id),on=s.offline.downloadedPacks.includes(id);return `<div class="card flat"><div class="progress-row"><div><strong>${sub.icon} ${esc(sub.name)}</strong><p>${on?'Saved on this device':'Not downloaded'}</p></div><button class="btn ${on?'secondary':'primary'} small" data-pack="${id}">${on?'Remove':'Download'}</button></div></div>`}).join('')}</div><div class="modal-actions"><button class="btn secondary" id="closePack">Done</button></div>`, el=>{
      $$('[data-pack]',el).forEach(b=>b.onclick=async()=>{const id=b.dataset.pack;const already=Store.get().offline.downloadedPacks.includes(id);if(!already){try{await Store.savePack(id,{subjectId:id,lessons:D.lessons.filter(l=>l.subjectId===id),questions:D.questions.filter(q=>q.subjectId===id)});}catch{} Store.patch(st=>st.offline.downloadedPacks.push(id)); toast(`${subject(id).name} saved for offline study.`);}else Store.patch(st=>st.offline.downloadedPacks=st.offline.downloadedPacks.filter(x=>x!==id)); closeModal();downloadModal();}); $('#closePack',el).onclick=closeModal;
    });
  }

  function skipFlow(){
    const st=Store.get(), track=E.getTrack(st.user.selectedTrackId), used=st.restDaysUsed||0, left=Math.max(0,track.restDays-used);
    showModal(`<h2>Got it. Choose one.</h2><p>No reason is required.</p><div class="grid" style="margin-top:18px"><button class="btn secondary" id="fiveQ">Do 5 questions instead, about 4 minutes</button><button class="btn secondary" id="reschedule">Reschedule to tonight</button><button class="btn secondary" id="restDay">Take a rest day, ${left} left</button></div>`,el=>{
      $('#fiveQ',el).onclick=()=>{closeModal();go('practice?quick=5');render();};
      $('#reschedule',el).onclick=()=>{Store.patch(s=>{const n=s.today.sessions.find(x=>x.status==='next');if(n)n.time='20:00';});closeModal();toast('Session moved to 8:00 PM.');render();};
      $('#restDay',el).onclick=()=>{if(left<=0)return toast('No rest days remain on this track.');Store.patch(s=>{s.restDaysUsed=(s.restDaysUsed||0)+1;s.today.sessions.forEach(x=>{if(x.status!=='done')x.status='rest';});});closeModal();toast('Rest day recorded. No streak reset, no guilt message.');render();};
    });
  }

  function emotionalCheckin(sessionId, cb){
    showModal(`<span class="eyebrow">90-second calibration</span><h2>How is your brain showing up right now?</h2><p>This adjusts the session. It is study-performance data, not a medical diagnosis.</p><div class="choice-grid" style="margin-top:18px">${[['tired','Tired'],['stressed','Stressed'],['okay','Okay'],['good','Good'],['focused','Focused']].map(([id,l])=>`<button class="choice" data-feel="${id}">${l}</button>`).join('')}</div>`,el=>$$('[data-feel]',el).forEach(b=>b.onclick=()=>{const feel=b.dataset.feel;Store.patch(s=>{s.today.emotionalState=feel;s.checkInHistory.push({state:feel,date:new Date().toISOString()}); if(feel==='tired')s.today.mode='low';if(feel==='focused')s.today.mode='power';});closeModal(); if(feel==='stressed') breathing(cb); else cb(feel);}));
  }
  function breathing(cb){ let sec=20; showModal(`<h2>Two-minute reset</h2><p>This demo uses a short preview. Breathe slowly, then begin with familiar questions.</p><div class="lesson-visual"><div><div class="big">○</div><h3 id="breathText">Breathe in</h3><p><span id="breathSec">${sec}</span> seconds</p></div></div>`); const t=setInterval(()=>{sec--;$('#breathSec')&&($('#breathSec').textContent=sec);if($('#breathText'))$('#breathText').textContent=sec%8<4?'Breathe out':'Breathe in';if(sec<=0){clearInterval(t);closeModal();cb('stressed');}},1000);modalCleanup=()=>clearInterval(t); }

  function startSession(id){
    const st=Store.get(), sess=st.today.sessions.find(x=>x.id===id) || st.today.sessions.find(x=>x.status!=='done');
    if(!sess)return toast('No session is ready right now.');
    emotionalCheckin(sess.id,()=>{studyCtx={sessionId:sess.id,lessonId:sess.lessonId||D.lessons[0].id,step:0,recallIndex:0,recallResults:[],applyIndex:0};go(`study-session`);render();});
  }

  function studyPage(){
    const s=Store.get(); if(!studyCtx){
      return `<div class="page"><div class="page-head"><div><span class="eyebrow">Study</span><h1>Your learning plan</h1><p>New topics use See It, Hear It, Recall It and Apply It. Reviews are inserted automatically.</p></div></div><div class="grid two">${D.lessons.filter(l=>s.user.subjects.includes(l.subjectId)).map(l=>`<div class="card"><span class="status info">${subject(l.subjectId).name}</span><h3 style="margin-top:10px">${esc(l.title)}</h3><p>${l.duration} min · ${l.complexity} topic</p><button class="btn primary small" data-lesson="${l.id}" style="margin-top:14px">Start learning loop</button></div>`).join('')}</div><div class="section-title"><h2>Due reviews</h2><p>${s.spacedQueue.filter(x=>x.status==='due').length} due now</p></div><div class="grid two">${s.spacedQueue.map(r=>`<div class="card flat"><strong>${esc(r.topic)}</strong><p>${subject(r.subjectId).name} · cycle ${r.cycle} · ${r.status}</p><button class="btn secondary small" data-review="${r.id}" style="margin-top:10px">Review</button></div>`).join('')}</div></div>`;
    }
    return studySessionView();
  }

  function bindStudy(){
    $$('[data-lesson]').forEach(b=>b.onclick=()=>{studyCtx={sessionId:null,lessonId:b.dataset.lesson,step:0,recallIndex:0,recallResults:[],applyIndex:0};go('study-session');render();});
    $$('[data-review]').forEach(b=>b.onclick=()=>{const r=Store.get().spacedQueue.find(x=>x.id===b.dataset.review); const l=D.lessons.find(x=>x.subjectId===r.subjectId)||D.lessons[0];studyCtx={sessionId:null,lessonId:l.id,step:2,recallIndex:0,recallResults:[],applyIndex:0,reviewId:r.id};go('study-session');render();});
  }

  function studySessionView(){
    const ctx=studyCtx, lesson=D.lessons.find(x=>x.id===ctx.lessonId)||D.lessons[0], s=Store.get();
    const labels=['See It','Hear It','Recall It','Apply It'];
    let body='';
    if(ctx.step===0) body=`<div class="lesson-visual"><div><div class="big">${esc(lesson.see.icon)}</div><h2>${esc(lesson.see.title)}</h2>${lesson.see.lines.slice(0,6).map(x=>`<p>${esc(x)}</p>`).join('')}</div></div><div class="modal-actions"><button class="btn primary" id="studyNext">I can see it</button></div>`;
    if(ctx.step===1) body=`<div class="card"><span class="eyebrow">Plain-language audio</span><h2>${esc(lesson.title)}</h2><p id="hearText" style="font-size:1.12rem">${esc(lesson.hear.text)}</p><div class="action-strip" style="margin-top:16px"><button class="btn soft" id="speakBtn">Listen</button><button class="btn primary" id="studyNext">Continue</button></div></div>`;
    if(ctx.step===2){const q=lesson.recall[ctx.recallIndex];body=`<div class="question"><span class="eyebrow">From memory · ${ctx.recallIndex+1}/3</span><h2>${esc(q.q)}</h2><div class="field" style="margin-top:16px"><label>Your answer</label><input id="recallAnswer" autocomplete="off" placeholder="Say it or type it"></div><div class="action-strip" style="margin-top:14px">${s.user.settings.voiceInput?'<button class="btn secondary" id="voiceBtn">Use voice</button>':''}<button class="btn primary" id="checkRecall">Check answer</button></div><div id="recallFeedback"></div></div>`;}
    if(ctx.step===3){const qs=D.questions.filter(q=>q.subjectId===lesson.subjectId).slice(0,5);const q=qs[ctx.applyIndex%qs.length];body=`<div class="question"><span class="eyebrow">Past-exam style practice · ${Math.min(ctx.applyIndex+1,qs.length)}/${qs.length}</span><h2>${esc(q.stem)}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option" data-apply-option="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="applyFeedback"></div></div>`;}
    return `<div class="page study-shell"><div class="study-top"><div class="progress-row"><div><a href="#study" class="btn ghost small" id="exitStudy">← Exit</a> <strong>${esc(subject(lesson.subjectId).name)}</strong></div><div class="timer" id="sessionTimer">${formatTimer()}</div></div><div class="encode-step">${labels.map((_,i)=>`<span class="${i<ctx.step?'done':i===ctx.step?'active':''}"></span>`).join('')}</div><div class="progress-row"><strong>${labels[ctx.step]}</strong><span>${lesson.duration} min loop</span></div></div>${body}</div>`;
  }

  function formatTimer(){ const m=Math.floor(sessionSeconds/60),sec=sessionSeconds%60;return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`; }
  function ensureTimer(){ if(sessionTimer)return;sessionTimer=setInterval(()=>{sessionSeconds++;if($('#sessionTimer'))$('#sessionTimer').textContent=formatTimer();if(sessionSeconds===45*60){clearInterval(sessionTimer);sessionTimer=null;hyperfocusBreak();}},1000); }
  function hyperfocusBreak(){ showModal(`<h2>45 minutes reached</h2><p>You have done enough continuous work. Take a break before continuing. Hyperfocus is useful, but recovery protects retention.</p><div class="modal-actions"><button class="btn primary" id="breakOk">Start a break</button></div>`,el=>$('#breakOk',el).onclick=()=>{closeModal();toast('Break started. Return when you are ready.');}); }
  function speak(text){ if(!('speechSynthesis' in window))return toast('Read-aloud is not supported in this browser.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.92;speechSynthesis.speak(u); }
  function voiceInput(target){ const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return toast('Voice input is not supported in this browser.');const r=new R();r.lang='en-NG';r.onresult=e=>{target.value=e.results[0][0].transcript;};r.start(); }

  function bindStudySession(){
    ensureTimer();
    $('#exitStudy')?.addEventListener('click',()=>{cleanupTransient();studyCtx=null;});
    $('#speakBtn')?.addEventListener('click',()=>speak($('#hearText').textContent));
    $('#studyNext')?.addEventListener('click',()=>{studyCtx.step++;render();});
    $('#voiceBtn')?.addEventListener('click',()=>voiceInput($('#recallAnswer')));
    $('#checkRecall')?.addEventListener('click',()=>{const lesson=D.lessons.find(x=>x.id===studyCtx.lessonId),q=lesson.recall[studyCtx.recallIndex],ans=$('#recallAnswer').value.trim().toLowerCase(),keywords=q.a.toLowerCase().split(/\s+|\//).filter(x=>x.length>2),ok=keywords.some(k=>ans.includes(k));const f=$('#recallFeedback');f.innerHTML=`<div class="feedback ${ok?'good':'retry'}"><strong>${ok?'That retrieval worked.':'Try a different mental route.'}</strong><p>${ok?`Expected idea: ${esc(q.a)}`:esc(lesson.alternateAnalogy)}</p><button class="btn ${ok?'primary':'secondary'} small" id="nextRecall" style="margin-top:10px">${studyCtx.recallIndex>=2?'Move to Apply It':'Next recall'}</button></div>`;$('#nextRecall').onclick=()=>{studyCtx.recallResults.push(ok);if(studyCtx.recallIndex>=2){studyCtx.step=3;}else studyCtx.recallIndex++;render();};});
    $$('[data-apply-option]').forEach(b=>b.onclick=()=>{const lesson=D.lessons.find(x=>x.id===studyCtx.lessonId),qs=D.questions.filter(q=>q.subjectId===lesson.subjectId).slice(0,5),q=qs[studyCtx.applyIndex%qs.length],idx=Number(b.dataset.applyOption),ok=idx===q.answer;$$('[data-apply-option]').forEach(x=>x.disabled=true);b.classList.add('chosen');$('#applyFeedback').innerHTML=`<div class="feedback ${ok?'good':'retry'}"><strong>${ok?'Correct.':'Not yet. Here is the reason.'}</strong><p>${esc(q.explanation)}</p><button class="btn soft small" id="listenExplain">Listen to explanation</button> <button class="btn primary small" id="nextApply">${studyCtx.applyIndex>=qs.length-1?'Finish session':'Next question'}</button></div>`;$('#listenExplain').onclick=()=>speak(q.explanation);$('#nextApply').onclick=()=>{recordAnswer(q,ok,idx); if(studyCtx.applyIndex>=qs.length-1)finishStudy(lesson);else{studyCtx.applyIndex++;render();}};});
  }

  function recordAnswer(q,ok,idx){
    Store.patch(s=>{s.answers.push({questionId:q.id,correct:ok,chosen:idx,at:new Date().toISOString()});if(!ok){let item=s.mistakeBank.find(x=>x.questionId===q.id);const updated=E.updateMistake(item,false);if(item)Object.assign(item,updated);else s.mistakeBank.push({...updated,questionId:q.id,subjectId:q.subjectId,topic:q.topic});} s.user.xp+=ok?8:3; if(!navigator.onLine){s.offline.pendingSync++;}});
  }
  function finishStudy(lesson){
    const now=E.isoDate(new Date());Store.patch(s=>{s.sessionsCompleted++;s.minutesStudied+=Math.max(lesson.duration,Math.ceil(sessionSeconds/60));s.user.xp+=35;if(studyCtx.sessionId){const x=s.today.sessions.find(y=>y.id===studyCtx.sessionId);if(x)x.status='done';const next=s.today.sessions.find(y=>!['done','rest'].includes(y.status));if(next)next.status='next';}if(studyCtx.reviewId){const r=s.spacedQueue.find(x=>x.id===studyCtx.reviewId);if(r)r.status='done';s.reviewsCompleted++;}s.score.updatedAt=new Date().toISOString();});cleanupTransient();studyCtx=null;showModal(`<h2>Session complete</h2><p>You finished the learning loop. Your progress has been recorded${navigator.onLine?'.':', and it will sync when you reconnect.'}</p><div class="grid two" style="margin-top:16px"><div class="metric"><div class="metric-label">XP earned</div><div class="metric-value">+35</div></div><div class="metric"><div class="metric-label">Time</div><div class="metric-value">${Math.max(lesson.duration,Math.ceil(sessionSeconds/60))}m</div></div></div><div class="modal-actions"><button class="btn primary" id="backHome">Back home</button></div>`,el=>$('#backHome',el).onclick=()=>{closeModal();go('home');render();});sessionSeconds=0;
  }

  function practicePage(){
    const st=Store.get(), due=st.mistakeBank.filter(x=>x.nextDue && x.nextDue<=E.isoDate(new Date())).length;
    return `<div class="page"><div class="page-head"><div><span class="eyebrow">Practice</span><h1>Question drills</h1><p>Short practice sets keep switching costs manageable and feed mistakes back into your review plan.</p></div></div><div class="grid three"><button class="card" data-drill="mixed" style="text-align:left"><h3>Mixed sprint</h3><p>10 questions across your subjects.</p></button><button class="card" data-drill="weak" style="text-align:left"><h3>Weak-topic drill</h3><p>Questions from your current mistake bank.</p></button><button class="card" data-drill="challenge" style="text-align:left"><h3>Challenge Mode</h3><p>Fast 5-question sprint with bonus XP.</p></button></div><div class="section-title"><h2>By subject</h2><p>Demo question bank</p></div><div class="grid three">${st.user.subjects.map(id=>{const x=subject(id),n=D.questions.filter(q=>q.subjectId===id).length;return `<button class="card flat" data-subject-drill="${id}" style="text-align:left"><h3>${x.icon} ${esc(x.name)}</h3><p>${n} illustrative questions currently loaded</p></button>`}).join('')}</div><div class="callout warning" style="margin-top:18px"><strong>${due} mistake-bank questions due</strong><p>Incorrect answers are re-served until you get 3 consecutive correct answers.</p><a href="#mistake-bank" class="btn warning small" style="margin-top:10px">Review due mistakes</a></div></div>`;
  }
  function bindPractice(){ $$('[data-drill]').forEach(b=>b.onclick=()=>startDrill(b.dataset.drill));$$('[data-subject-drill]').forEach(b=>b.onclick=()=>startDrill('subject',b.dataset.subjectDrill)); }
  function startDrill(type,subjectId){ let qs=[];if(type==='weak'){qs=Store.get().mistakeBank.map(x=>question(x.questionId)).filter(Boolean);}else if(type==='subject'){qs=D.questions.filter(q=>q.subjectId===subjectId);}else qs=D.questions.filter(q=>Store.get().user.subjects.includes(q.subjectId));qs=qs.slice(0,type==='challenge'?5:10);drillModal(qs,type==='challenge'); }
  function drillModal(qs,challenge=false){ if(!qs.length)return toast('No questions are available for this set yet.');let i=0,score=0;const draw=()=>{const q=qs[i];showModal(`<div class="progress-row"><span class="eyebrow">${challenge?'Challenge Mode':'Practice'} · ${i+1}/${qs.length}</span><strong>${score} correct</strong></div><div class="question"><h2>${esc(q.stem)}</h2><div class="option-list">${q.options.map((o,j)=>`<button class="option" data-dopt="${j}">${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}</div><div id="dfeed"></div></div>`,el=>$$('[data-dopt]',el).forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.dopt)===q.answer;if(ok)score++;recordAnswer(q,ok,Number(b.dataset.dopt));$$('[data-dopt]',el).forEach(x=>x.disabled=true);$('#dfeed',el).innerHTML=`<div class="feedback ${ok?'good':'retry'}"><strong>${ok?'Correct.':'Use this explanation.'}</strong><p>${esc(q.explanation)}</p><button id="dnext" class="btn primary small" style="margin-top:10px">${i===qs.length-1?'Finish':'Next'}</button></div>`;$('#dnext',el).onclick=()=>{if(i===qs.length-1){Store.patch(s=>s.user.xp+=challenge?50:25);closeModal();toast(`Set complete. ${score}/${qs.length} correct.`);render();}else{i++;draw();}};}));};draw(); }

  function mocksPage(){
    const s=Store.get(), phase=E.mockPhase(s.user.currentDay), last=s.mockHistory.at(-1);
    return `<div class="page"><div class="page-head"><div><span class="eyebrow">Phase ${phase.phase}: ${phase.name}</span><h1>Mock exams</h1><p>Mocks measure exam execution, not only score. Timing, fatigue, flagging, changed answers and subject order all matter.</p></div><button class="btn primary" id="startMock">Start demo mock</button></div><div class="grid four"><div class="metric"><div class="metric-label">Latest score</div><div class="metric-value">${last?`${last.score}/400`:'Not taken'}</div></div><div class="metric"><div class="metric-label">Time</div><div class="metric-value">${last?`${last.timeMin}m`:'—'}</div></div><div class="metric"><div class="metric-label">First 10</div><div class="metric-value">${last?`${last.first10}%`:'—'}</div></div><div class="metric"><div class="metric-label">Last 10</div><div class="metric-value">${last?`${last.last10}%`:'—'}</div></div></div><div class="section-title"><h2>Mock history</h2><p>${phase.cadence}</p></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Score</th><th>First vs last</th><th>Flags</th><th>Changed answers</th></tr></thead><tbody>${s.mockHistory.map(m=>`<tr><td>${fmtDate(m.date)}</td><td><strong>${m.score}/400</strong></td><td>${m.first10}% / ${m.last10}%</td><td>${m.flagged}, returned ${m.returned}</td><td>${m.changed}, helped ${m.changesHelped}</td></tr>`).join('')}</tbody></table></div><div class="grid two" style="margin-top:18px"><div class="card"><h3>Optional Distraction Mode</h3><p>Available in the later simulation phase. You choose background noise. It is never imposed.</p><button id="distractionInfo" class="btn secondary small" style="margin-top:12px">How it works</button></div><div class="card"><h3>Infrastructure failures are not simulated</h3><p>NeuroPass never deliberately slows the app or simulates poor internet as an exam challenge.</p></div></div></div>`;
  }
  function bindMocks(){ $('#startMock')?.addEventListener('click',startMock);$('#distractionInfo')?.addEventListener('click',()=>showModal(`<h2>Distraction Mode is optional</h2><p>In a later mock phase, you may activate mild background sound as a focus-resilience challenge. Week 12 can optionally include one simulated notification. Slow internet is never simulated.</p><div class="modal-actions"><button class="btn primary" onclick="document.querySelector('.modal-backdrop').remove()">Understood</button></div>`)); }
  function startMock(){ const qs=D.questions.filter(q=>Store.get().user.subjects.includes(q.subjectId)).slice(0,10);mockCtx={qs,index:0,answers:Array(qs.length).fill(null),flags:new Set(),started:Date.now(),qStarted:Date.now(),times:[],changes:0,changesHelped:0};go('mock-live');render(); }
  function mockLive(){ if(!mockCtx){go('mocks');return '';}const q=mockCtx.qs[mockCtx.index];return `<div class="page"><div class="page-head"><div><span class="eyebrow">Demo mock</span><h1>Question ${mockCtx.index+1} of ${mockCtx.qs.length}</h1><p>Telemetry is recorded locally for this demo.</p></div><button class="btn secondary" id="finishMock">Finish mock</button></div><div class="mock-grid"><div class="question"><span class="status info">${subject(q.subjectId).name}</span><h2 style="margin-top:14px">${esc(q.stem)}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option ${mockCtx.answers[mockCtx.index]===i?'chosen':''}" data-mopt="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div class="action-strip" style="margin-top:16px"><button id="prevMock" class="btn secondary" ${mockCtx.index===0?'disabled':''}>Previous</button><button id="flagMock" class="btn warning">${mockCtx.flags.has(mockCtx.index)?'Unflag':'Flag'} question</button><button id="nextMock" class="btn primary">${mockCtx.index===mockCtx.qs.length-1?'Review':'Next'}</button></div></div><aside class="mock-side card flat"><h3>Question map</h3><div class="question-index">${mockCtx.qs.map((_,i)=>`<button class="qnum ${mockCtx.answers[i]!=null?'answered':''} ${mockCtx.flags.has(i)?'flagged':''}" data-qnum="${i}">${i+1}</button>`).join('')}</div><p style="margin-top:14px">Answered: ${mockCtx.answers.filter(x=>x!=null).length}/${mockCtx.qs.length}</p></aside></div></div>`; }
  function bindMockLive(){ const move=n=>{mockCtx.times[mockCtx.index]=(mockCtx.times[mockCtx.index]||0)+(Date.now()-mockCtx.qStarted);mockCtx.index=E.clamp(n,0,mockCtx.qs.length-1);mockCtx.qStarted=Date.now();render();};$$('[data-mopt]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.mopt),old=mockCtx.answers[mockCtx.index];if(old!=null&&old!==idx){mockCtx.changes++;if(idx===mockCtx.qs[mockCtx.index].answer)mockCtx.changesHelped++;}mockCtx.answers[mockCtx.index]=idx;render();});$$('[data-qnum]').forEach(b=>b.onclick=()=>move(Number(b.dataset.qnum)));$('#prevMock').onclick=()=>move(mockCtx.index-1);$('#nextMock').onclick=()=>mockCtx.index===mockCtx.qs.length-1?mockReview():move(mockCtx.index+1);$('#flagMock').onclick=()=>{mockCtx.flags.has(mockCtx.index)?mockCtx.flags.delete(mockCtx.index):mockCtx.flags.add(mockCtx.index);render();};$('#finishMock').onclick=mockReview; }
  function mockReview(){ const unanswered=mockCtx.answers.filter(x=>x==null).length;showModal(`<h2>Submit this mock?</h2><p>${unanswered?`${unanswered} questions are unanswered.`:'Every question has an answer.'} You flagged ${mockCtx.flags.size}.</p><div class="modal-actions"><button class="btn secondary" id="returnMock">Return</button><button class="btn primary" id="submitMock">Submit</button></div>`,el=>{$('#returnMock',el).onclick=closeModal;$('#submitMock',el).onclick=submitMock;}); }
  function submitMock(){ mockCtx.times[mockCtx.index]=(mockCtx.times[mockCtx.index]||0)+(Date.now()-mockCtx.qStarted);const correct=mockCtx.qs.reduce((n,q,i)=>n+(mockCtx.answers[i]===q.answer?1:0),0), pct=Math.round(correct/mockCtx.qs.length*100),scaled=Math.round(pct*4),first=Math.round(mockCtx.qs.slice(0,5).reduce((n,q,i)=>n+(mockCtx.answers[i]===q.answer?1:0),0)/5*100),last=Math.round(mockCtx.qs.slice(-5).reduce((n,q,j)=>{const i=mockCtx.qs.length-5+j;return n+(mockCtx.answers[i]===q.answer?1:0)},0)/5*100);Store.patch(s=>{s.mockHistory.push({id:`mock_${Date.now()}`,date:E.isoDate(new Date()),score:scaled,percent:pct,timeMin:Math.max(1,Math.round((Date.now()-mockCtx.started)/60000)),first10:first,last10:last,flagged:mockCtx.flags.size,returned:mockCtx.flags.size,changed:mockCtx.changes,changesHelped:mockCtx.changesHelped,subjectOrder:[...new Set(mockCtx.qs.map(q=>subject(q.subjectId).short))]});s.user.xp+=100;});closeModal();const result={scaled,pct,correct,total:mockCtx.qs.length};mockCtx=null;showModal(`<h2>Mock complete</h2><div class="metric"><div class="metric-label">Score</div><div class="metric-value">${result.scaled}/400</div><div class="metric-sub">${result.correct}/${result.total} correct in the demo set</div></div><p style="margin-top:14px">NeuroPass saved timing, flags, answer changes and early-vs-late accuracy.</p><div class="modal-actions"><button class="btn primary" id="mockDone">View mocks</button></div>`,el=>$('#mockDone',el).onclick=()=>{closeModal();go('mocks');render();}); }

  function mistakePage(){ const s=Store.get(), today=E.isoDate(new Date());return `<div class="page"><div class="page-head"><div><span class="eyebrow">Retention engineering</span><h1>Mistake Bank</h1><p>A weakness is not abandoned. A wrong question returns after 3 days, then 2 days after another miss, until you answer it correctly 3 times in a row.</p></div></div><div class="grid two">${s.mistakeBank.length?s.mistakeBank.map(x=>{const q=question(x.questionId);return `<div class="card"><div class="progress-row"><span class="status ${x.mastered?'success':x.nextDue<=today?'warning':'neutral'}">${x.mastered?'Mastered':x.nextDue<=today?'Due now':'Scheduled'}</span><span>${x.consecutiveCorrect||0}/3 correct streak</span></div><h3>${esc(q?.stem||x.topic)}</h3><p>${subject(x.subjectId).name} · ${esc(x.topic)}</p><p style="margin-top:8px">Next due: ${x.nextDue?fmtDate(x.nextDue):'Completed'}</p>${!x.mastered?`<button class="btn primary small" data-mistake="${x.questionId}" style="margin-top:12px">Review question</button>`:''}</div>`}).join(''):'<div class="callout success"><strong>No active mistakes</strong><p>Questions you miss will appear here automatically.</p></div>'}</div></div>`; }
  function bindMistakes(){ $$('[data-mistake]').forEach(b=>b.onclick=()=>drillModal([question(b.dataset.mistake)].filter(Boolean))); }

  function progressPage(){ const s=Store.get(),track=E.getTrack(s.user.selectedTrackId),daysRemain=Math.max(0,track.days-s.user.currentDay),comp=E.complianceStatus({rollingAverage:s.compliance.rollingAverage,consecutiveBelow70:s.compliance.consecutiveBelow70,daysRemaining:daysRemain});return `<div class="page"><div class="page-head"><div><span class="eyebrow">Progress</span><h1>Your work, not a streak</h1><p>NeuroPass uses rolling compliance because one difficult week should trigger recovery, not erase the work already done.</p></div>${status(comp.label,comp.tone)}</div><div class="grid three"><div class="metric"><div class="metric-label">Sessions completed</div><div class="metric-value">${s.sessionsCompleted}</div></div><div class="metric"><div class="metric-label">Study time</div><div class="metric-value">${Math.round(s.minutesStudied/60)}h</div></div><div class="metric"><div class="metric-label">Reviews completed</div><div class="metric-value">${s.reviewsCompleted}</div></div></div><div class="section-title"><h2>Rolling compliance</h2><p>${s.compliance.rollingAverage}% average</p></div><div class="card">${progress(s.compliance.rollingAverage)}<div class="grid" style="grid-template-columns:repeat(${Math.min(10,s.compliance.weekly.length)},1fr);gap:5px;margin-top:16px">${s.compliance.weekly.slice(-10).map((n,i)=>`<div title="Week ${i+1}: ${n}%"><div style="height:${Math.max(30,n)}px;background:${n<70?'var(--warning)':'var(--brand)'};border-radius:7px 7px 3px 3px"></div><small>${n}</small></div>`).join('')}</div></div><div class="section-title"><h2>Guarantee audit trail</h2><p>Inspectable, not hidden</p></div><div class="timeline">${s.compliance.events.map(e=>`<div class="timeline-item"><div class="timeline-dot"></div><div><strong>${esc(e.text)}</strong><br><small>${fmtDate(e.date)}</small></div></div>`).join('')}</div><div class="section-title"><h2>Mock trend</h2><p>Latest ${s.mockHistory.length} mocks</p></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Score</th><th>Accuracy</th><th>Execution note</th></tr></thead><tbody>${s.mockHistory.map(m=>`<tr><td>${fmtDate(m.date)}</td><td>${m.score}/400</td><td>${m.percent}%</td><td>${m.last10<m.first10?'Late-question fade detected':'Stable through the end'}</td></tr>`).join('')}</tbody></table></div><div class="section-title"><h2>After your real exam</h2><p>This closes the validation loop</p></div><div class="card"><h3>Submit your actual result</h3><p>Your result is compared with the model’s prediction to improve future projections.</p><button id="submitOutcome" class="btn secondary small" style="margin-top:12px">Enter result</button></div></div>`; }
  function bindProgress(){ $('#submitOutcome')?.addEventListener('click',outcomeModal); }
  function outcomeModal(){ const s=Store.get();showModal(`<h2>Post-exam result</h2><p>Enter your official total score after your exam.</p><div class="field" style="margin-top:16px"><label>Actual score out of 400</label><input id="actualScore" type="number" min="0" max="400"></div><div class="modal-actions"><button class="btn secondary" id="cancelOutcome">Cancel</button><button class="btn primary" id="saveOutcome">Save result</button></div>`,el=>{$('#cancelOutcome',el).onclick=closeModal;$('#saveOutcome',el).onclick=()=>{const actual=Number($('#actualScore',el).value);if(!Number.isFinite(actual)||actual<0||actual>400)return toast('Enter a score from 0 to 400.');Store.patch(st=>st.postExamOutcomes.push({id:`out_${Date.now()}`,studentId:st.user.id,actualScore:actual,predictedScore:st.score.projected,error:actual-st.score.projected,guaranteed:st.score.guaranteed,compliance:st.compliance.rollingAverage,trackId:st.user.selectedTrackId,modelVersion:st.score.modelVersion,date:E.isoDate(new Date())}));closeModal();toast('Result saved to the validation dataset.');render();};}); }

  function coachPage(){ const s=Store.get();return `<div class="page"><div class="page-head"><div><span class="eyebrow">Human touchpoint</span><h1>${esc(s.coach.assigned.name)}</h1><p>Your Learning Coach can help with consistency, a failed mock or a recovery plan. This is not peer mentoring.</p></div>${status('Assigned coach','success')}</div><div class="card"><div class="session-list">${s.coach.messages.map(m=>`<div class="callout ${m.from==='coach'?'info':''}"><strong>${m.from==='coach'?s.coach.assigned.name:'You'}</strong><p>${esc(m.text)}</p><small>${new Date(m.date).toLocaleString()}</small></div>`).join('')}</div><form id="coachMessage" class="action-strip" style="margin-top:16px"><input name="msg" aria-label="Message" placeholder="Write a message" style="flex:1;min-width:180px;border:1px solid var(--line);border-radius:12px;padding:10px" required><button class="btn primary">Send</button></form>${!navigator.onLine?'<p style="margin-top:8px">Message will be queued until you reconnect.</p>':''}</div><div class="section-title"><h2>Touchpoints</h2><p>Scheduled around real risk moments</p></div><div class="grid two">${s.coach.touchpoints.map(t=>`<div class="card flat"><div class="progress-row"><strong>${esc(t.moment)}</strong>${status(t.status,t.status==='completed'?'success':'info')}</div><p>${fmtDate(t.date)} · ${esc(t.notes)}</p></div>`).join('')}</div></div>`; }
  function bindCoach(){ $('#coachMessage')?.addEventListener('submit',e=>{e.preventDefault();const text=new FormData(e.target).get('msg').trim();if(!text)return;Store.patch(s=>{s.coach.messages.push({id:`m_${Date.now()}`,from:'student',date:new Date().toISOString(),text});if(!navigator.onLine)s.offline.pendingSync++;});render();toast(navigator.onLine?'Message sent.':'Message queued for sync.');}); }

  function parentShare(){ const s=Store.get(),t=E.getTrack(s.user.selectedTrackId);return `<div class="page"><div class="page-head"><div><span class="eyebrow">Share with parent or guardian</span><h1>${esc(s.user.firstName)}’s exam preparation plan</h1><p>This page focuses on the study plan and expected exam outcome. A medical diagnosis is not required.</p></div><button class="btn primary" id="copyShare">Copy summary</button></div><section class="card hero-card"><h2>${t.name} track</h2><p>${t.days} days · ${t.hours} study hours per day · ${s.user.examType} preparation</p><div class="grid three" style="margin-top:16px"><div><div class="metric-label" style="color:#d8ecf6">Current projection</div><div class="metric-value">${s.score.projected}/400</div></div><div><div class="metric-label" style="color:#d8ecf6">Current guaranteed minimum</div><div class="metric-value">${s.score.guaranteed}/400</div></div><div><div class="metric-label" style="color:#d8ecf6">Compliance</div><div class="metric-value">${s.compliance.rollingAverage}%</div></div></div></section><div class="grid two" style="margin-top:18px"><div class="card"><h3>How NeuroPass teaches</h3><p>Short visual and audio explanations, memory retrieval, exam-style practice, spaced repetition and automatic mistake review.</p></div><div class="card"><h3>How support works</h3><p>A trained Learning Coach is assigned for specific risk moments. Low Energy sessions and rest days help students recover without losing the whole plan.</p></div></div><div class="callout warning" style="margin-top:18px"><strong>Important guarantee condition</strong><p>The guarantee is a shared commitment and depends on assigned sessions, mocks, schedule adherence and at least 80% average compliance. No track guarantees 400/400. Public guarantee language still requires legal approval before launch.</p></div></div>`; }
  function bindParentShare(){ $('#copyShare')?.addEventListener('click',async()=>{const s=Store.get(),t=E.getTrack(s.user.selectedTrackId),text=`NeuroPass ${t.name} plan for ${s.user.firstName}: ${t.days} days, ${t.hours} hrs/day. Current projection ${s.score.projected}/400, current guaranteed minimum ${s.score.guaranteed}/400, rolling compliance ${s.compliance.rollingAverage}%. Guarantee eligibility requires assigned sessions, mocks, schedule adherence and 80% average compliance.`;try{await navigator.clipboard.writeText(text);toast('Parent summary copied.');}catch{toast('Copy is not available in this browser.');}}); }

  function settingsPage(){ const s=Store.get(),a=s.user.settings;const toggle=(key,label,desc)=>`<div class="card flat"><div class="progress-row"><div><strong>${label}</strong><p>${desc}</p></div><button class="switch ${a[key]?'on':''}" data-toggle="${key}" aria-label="${label}"></button></div></div>`;return `<div class="page"><div class="page-head"><div><span class="eyebrow">Accessibility and control</span><h1>Settings</h1><p>No accommodation is locked. Change one setting or all of them at any time.</p></div></div><div class="grid two">${toggle('dyslexicFont','Dyslexia-friendly font','Uses a high-legibility fallback font in this web build.')} ${toggle('readAloud','Audio read-aloud','Questions, instructions and explanations can be spoken by the browser.')} ${toggle('karaoke','Karaoke highlighting','Highlight text in sync with supported speech output.')} ${toggle('chunkedReading','Chunked passages','Break long comprehension into 3-sentence chunks.')} ${toggle('syllableAssist','Syllable assist','Show difficult words in syllable chunks when content metadata is available.')} ${toggle('voiceInput','Voice input','Use browser speech recognition where supported.')} ${toggle('visibleTimer','Visible session timer','Keep time remaining or elapsed visible during study.')} ${toggle('notifications','Smart nudges','Direct action reminders without guilt language.')} ${toggle('reduceMotion','Reduce motion','Limit interface animation.')}</div><div class="section-title"><h2>Typography</h2><p>Adjust to your reading comfort</p></div><div class="card"><div class="form-grid"><div class="field"><label>Font size: <span id="fontSizeVal">${a.fontSize}px</span></label><input id="fontSizeRange" type="range" min="14" max="24" value="${a.fontSize}"></div><div class="field"><label>Line spacing: <span id="lineVal">${a.lineHeight}</span></label><input id="lineRange" type="range" min="1.3" max="2.1" step="0.1" value="${a.lineHeight}"></div><div class="field"><label>Letter spacing: <span id="letterVal">${a.letterSpacing}px</span></label><input id="letterRange" type="range" min="0" max="3" step="0.25" value="${a.letterSpacing}"></div><div class="field"><label>Background</label><select id="backgroundSelect"><option value="standard" ${a.background==='standard'?'selected':''}>Standard</option><option value="cream" ${a.background==='cream'?'selected':''}>Cream</option><option value="yellow" ${a.background==='yellow'?'selected':''}>Light yellow</option><option value="blue" ${a.background==='blue'?'selected':''}>Light blue</option></select></div></div></div><div class="section-title"><h2>Account and device</h2></div><div class="grid two"><div class="card"><h3>Offline sync</h3><p>Last sync: ${new Date(s.offline.lastSync).toLocaleString()}<br>Pending: ${s.offline.pendingSync}</p><button id="settingsSync" class="btn secondary small" style="margin-top:12px">Sync now</button></div><div class="card"><h3>Demo controls</h3><p>Reset the local demo state or sign out.</p><div class="action-strip" style="margin-top:12px"><button id="resetDemo" class="btn warning small">Reset demo</button><button id="signOut" class="btn secondary small">Sign out</button></div></div></div><div class="section-title"><h2>Future module</h2></div><div class="card"><h3>CFA · Coming Soon</h3><p>CFA content is not part of V1. Join the waitlist only.</p><a class="btn secondary small" href="#cfa-coming-soon" style="margin-top:10px">Open waitlist</a></div></div>`; }
  function bindSettings(){ $$('[data-toggle]').forEach(b=>b.onclick=()=>{const key=b.dataset.toggle;Store.patch(s=>s.user.settings[key]=!s.user.settings[key]);applySettings();render();});const ranges=[['fontSizeRange','fontSize','fontSizeVal',v=>`${v}px`],['lineRange','lineHeight','lineVal',v=>v],['letterRange','letterSpacing','letterVal',v=>`${v}px`]];ranges.forEach(([id,key,out,fmt])=>$('#'+id)?.addEventListener('input',e=>{const v=Number(e.target.value);Store.patch(s=>s.user.settings[key]=v);$('#'+out).textContent=fmt(v);applySettings();}));$('#backgroundSelect')?.addEventListener('change',e=>{Store.patch(s=>s.user.settings.background=e.target.value);applySettings();});$('#settingsSync')?.addEventListener('click',()=>{Store.flushQueue();toast('Sync state refreshed.');render();});$('#resetDemo')?.addEventListener('click',()=>{if(confirm('Reset all local demo progress?')){Store.reset();Store.patch(s=>s.authenticated=true);applySettings();go('home');render();}});$('#signOut')?.addEventListener('click',()=>{Store.patch(s=>s.authenticated=false);render();}); }

  function cfaPage(){ return `<div class="page"><div class="page-head"><div><span class="eyebrow">V2 waitlist only</span><h1>CFA is coming later</h1><p>No CFA teaching content ships in NeuroPass V1.</p></div></div><div class="card"><h3>Join the future-module waitlist</h3><form id="cfaForm" class="action-strip" style="margin-top:14px"><input name="email" type="email" required placeholder="Email address" style="flex:1;min-width:220px;border:1px solid var(--line);border-radius:12px;padding:10px"><button class="btn primary">Join waitlist</button></form></div></div>`; }
  function bindCfa(){ $('#cfaForm')?.addEventListener('submit',e=>{e.preventDefault();const email=new FormData(e.target).get('email');Store.patch(s=>s.cfaWaitlist.push({email,date:new Date().toISOString()}));toast('Added to the CFA waitlist.');e.target.reset();}); }

  function coachDashboard(){ const s=Store.get(),active=s.riskSignals.filter(x=>x.active);return `<div class="page"><div class="page-head"><div><span class="eyebrow">Learning Coach</span><h1>Support dashboard</h1><p>Human touchpoints appear at predefined risk moments. Peer mentor access is not part of V1.</p></div>${status(`${active.length} active signal${active.length===1?'':'s'}`,active.length?'warning':'success')}</div><div class="grid three"><div class="metric"><div class="metric-label">Assigned students</div><div class="metric-value">1</div></div><div class="metric"><div class="metric-label">Touchpoints due</div><div class="metric-value">${s.coach.touchpoints.filter(x=>x.status!=='completed').length}</div></div><div class="metric"><div class="metric-label">Active risk signals</div><div class="metric-value">${active.length}</div></div></div><div class="section-title"><h2>Priority queue</h2></div>${active.map(r=>`<div class="card"><div class="progress-row"><div><span class="status warning">${r.severity}</span><h3 style="margin-top:10px">${esc(r.title)}</h3></div><button class="btn primary small" data-open-risk="${r.id}">Open</button></div><p>${esc(r.detail)}</p></div>`).join('')||'<div class="callout success"><strong>No urgent cases</strong><p>Assigned students have no active escalation signal.</p></div>'}<div class="section-title"><h2>Upcoming touchpoints</h2></div><div class="grid two">${s.coach.touchpoints.map(t=>`<div class="card flat"><strong>${esc(t.moment)}</strong><p>${fmtDate(t.date)} · ${esc(t.notes)}</p>${status(t.status,t.status==='completed'?'success':'info')}</div>`).join('')}</div></div>`; }
  function bindCoachDashboard(){ $$('[data-open-risk]').forEach(b=>b.onclick=()=>{go('risk-queue');render();}); }
  function riskQueue(){ const s=Store.get();return `<div class="page"><div class="page-head"><div><span class="eyebrow">Explainable signals</span><h1>Risk queue</h1><p>Every alert states which behavior triggered it and what response is expected.</p></div></div>${s.riskSignals.map(r=>`<div class="card" style="margin-bottom:12px"><div class="progress-row"><div><h3>${esc(r.title)}</h3><p>Trigger: ${esc(r.trigger)}</p></div>${status(r.active?'Active':'Resolved',r.active?'warning':'success')}</div><p>${esc(r.detail)}</p>${r.active?'<div class="action-strip" style="margin-top:12px"><button class="btn primary small" data-resolve-risk="'+r.id+'">Log touchpoint and resolve</button><button class="btn secondary small" data-escalate="'+r.id+'">Escalate to senior coach</button></div>':''}</div>`).join('')}</div>`; }
  function bindRiskQueue(){ $$('[data-resolve-risk]').forEach(b=>b.onclick=()=>{Store.patch(s=>{const r=s.riskSignals.find(x=>x.id===b.dataset.resolveRisk);r.active=false;r.severity='resolved';s.coach.touchpoints.push({id:`tp_${Date.now()}`,moment:r.title,status:'completed',coach:s.coach.assigned.name,date:E.isoDate(new Date()),notes:'Coach touchpoint logged from risk queue.'});});toast('Touchpoint logged and signal resolved.');render();});$$('[data-escalate]').forEach(b=>b.onclick=()=>{Store.patch(s=>{const r=s.riskSignals.find(x=>x.id===b.dataset.escalate);r.severity='high';r.escalated=true;});toast('Escalated to Senior Coach.');render();}); }
  function assignedStudents(){ const s=Store.get();return `<div class="page"><div class="page-head"><div><span class="eyebrow">Assigned students</span><h1>Student view</h1></div></div><div class="card"><div class="progress-row"><div><h2>${esc(s.user.name)}</h2><p>${s.user.examType} · ${E.getTrack(s.user.selectedTrackId).name} · day ${s.user.currentDay}</p></div>${status(`${s.compliance.rollingAverage}% compliance`,s.compliance.rollingAverage>=80?'success':'warning')}</div><div class="grid three" style="margin-top:16px"><div class="metric"><div class="metric-label">Projection</div><div class="metric-value">${s.score.projected}</div></div><div class="metric"><div class="metric-label">Guarantee</div><div class="metric-value">${s.score.guaranteed}</div></div><div class="metric"><div class="metric-label">Latest mock</div><div class="metric-value">${s.mockHistory.at(-1).score}</div></div></div></div></div>`; }
  function coachInbox(){ return coachPage(); }

  function adminOverview(){ const s=Store.get(),legal=s.admin.legalReviewComplete,staff=s.admin.coachesStaffed;return `<div class="page"><div class="page-head"><div><span class="eyebrow">Administration</span><h1>NeuroPass V1 operations</h1><p>The load-bearing systems are visible here: retention, predictive logic, human touchpoints and post-exam validation.</p></div>${status(legal&&staff?'Launch preconditions met':'Not launch-ready',legal&&staff?'success':'danger')}</div><div class="grid four"><div class="metric"><div class="metric-label">Demo students</div><div class="metric-value">1</div></div><div class="metric"><div class="metric-label">Seed questions</div><div class="metric-value">${D.questions.length}</div></div><div class="metric"><div class="metric-label">Active risks</div><div class="metric-value">${s.riskSignals.filter(x=>x.active).length}</div></div><div class="metric"><div class="metric-label">Post-exam results</div><div class="metric-value">${s.postExamOutcomes.length}</div></div></div><div class="section-title"><h2>8 guarantee systems</h2><p>Load-bearing systems cannot be deferred</p></div><div class="grid two">${[['1','Precise Intake','Structural support'],['2','Friction Design','Finishing'],['3','Retention Engineering','Load-bearing'],['4','Emotional System','Structural support'],['5','Sophisticated Mocks','Finishing'],['6','Predictive Data Model','Load-bearing'],['7','Human Touchpoints','Load-bearing'],['8','Post-Exam Validation','Load-bearing']].map(([n,name,type])=>`<div class="card flat"><div class="progress-row"><strong>${n}. ${name}</strong>${status(type,type==='Load-bearing'?'info':'neutral')}</div><p>${['3','6','7','8'].includes(n)?'Required in V1 and represented in this build.':'Operational V1 system.'}</p></div>`).join('')}</div><div class="section-title"><h2>Recent audit events</h2></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th></tr></thead><tbody>${s.admin.audit.map(x=>`<tr><td>${new Date(x.date).toLocaleString()}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td></tr>`).join('')}</tbody></table></div></div>`; }
  function adminContent(){ return `<div class="page"><div class="page-head"><div><span class="eyebrow">Content manager</span><h1>Subjects, topics and lessons</h1><p>Power Topic status is a modeled estimate until verified against licensed source data and real user outcomes.</p></div></div><div class="grid three">${D.subjects.map(s=>`<div class="card"><h3>${s.icon} ${esc(s.name)}</h3><p>${D.topics.filter(t=>t.subjectId===s.id).length} Power Topics seeded · ${D.lessons.filter(l=>l.subjectId===s.id).length} demo lesson(s) · ${D.questions.filter(q=>q.subjectId===s.id).length} demo question(s)</p></div>`).join('')}</div><div class="section-title"><h2>Power Topics</h2><p>8+ appearances in last 10 papers is the intended rule</p></div><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Topic</th><th>Flag</th><th>Note</th></tr></thead><tbody>${D.topics.map(t=>`<tr><td>${subject(t.subjectId).short}</td><td>${esc(t.name)}</td><td>${status('Power Topic','info')}</td><td>Modeled until source dataset validation</td></tr>`).join('')}</tbody></table></div></div>`; }
  function adminImport(){ const s=Store.get();return `<div class="page"><div class="page-head"><div><span class="eyebrow">Question bank ingestion</span><h1>Import licensed questions</h1><p>The full JAMB and WAEC bank was not supplied with the scope document, so this build uses clearly marked illustrative demo questions.</p></div></div><div class="callout warning"><strong>Rights confirmation required</strong><p>Only import content you are authorized to use. Each row should preserve source and license metadata.</p></div><div class="card" style="margin-top:16px"><h3>CSV / JSON import</h3><p>Required fields: exam, year, subjectId, topic, stem, options, answer, explanation, source.</p><input id="questionFile" type="file" accept=".json,.csv,application/json,text/csv" style="margin-top:16px"><label class="check-row" style="margin-top:12px"><input id="rightsConfirm" type="checkbox"> I confirm the organization has rights to use this content.</label><button id="runImport" class="btn primary" style="margin-top:12px">Validate and import</button><div id="importResult"></div></div><div class="section-title"><h2>Import jobs</h2></div>${s.admin.importJobs.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>File</th><th>Status</th><th>Imported</th><th>Rejected</th></tr></thead><tbody>${s.admin.importJobs.map(j=>`<tr><td>${new Date(j.date).toLocaleString()}</td><td>${esc(j.file)}</td><td>${j.status}</td><td>${j.imported}</td><td>${j.rejected}</td></tr>`).join('')}</tbody></table></div>`:'<div class="callout info"><strong>No import jobs yet</strong><p>The seeded dataset remains illustrative only.</p></div>'}</div>`; }
  function bindAdminImport(){ $('#runImport')?.addEventListener('click',async()=>{const f=$('#questionFile').files[0];if(!f)return toast('Choose a CSV or JSON file.');if(!$('#rightsConfirm').checked)return toast('Confirm content rights before importing.');let rows=[];try{const text=await f.text();if(f.name.toLowerCase().endsWith('.json'))rows=JSON.parse(text);else{const lines=text.split(/\r?\n/).filter(Boolean),heads=lines.shift().split(',').map(x=>x.trim());rows=lines.map(line=>{const cells=line.split(',');const o={};heads.forEach((h,i)=>o[h]=cells[i]?.trim());if(typeof o.options==='string')o.options=o.options.split('|');o.answer=Number(o.answer);return o;});}if(!Array.isArray(rows))throw new Error('Root must be an array');}catch(e){return $('#importResult').innerHTML=`<div class="feedback retry">Could not parse file: ${esc(e.message)}</div>`;}const req=['exam','year','subjectId','topic','stem','options','answer','explanation','source'];const valid=[],bad=[];rows.forEach((r,i)=>{const missing=req.filter(k=>r[k]===undefined||r[k]===null||r[k]==='');if(!Array.isArray(r.options)||r.options.length<2)missing.push('options[]');if(!D.subjects.some(s=>s.id===r.subjectId))missing.push('valid subjectId');if(missing.length)bad.push({row:i+1,missing});else valid.push({...r,id:r.id||`imp_${Date.now()}_${i}`,licenseConfirmed:true});});Store.patch(s=>{s.importedQuestions.push(...valid);s.admin.importJobs.unshift({date:new Date().toISOString(),file:f.name,status:bad.length?'Completed with rejections':'Completed',imported:valid.length,rejected:bad.length});s.admin.audit.unshift({date:new Date().toISOString(),actor:'Admin',action:`Imported ${valid.length} questions from ${f.name}; ${bad.length} rejected`});});$('#importResult').innerHTML=`<div class="feedback ${bad.length?'retry':'good'}"><strong>${valid.length} imported, ${bad.length} rejected.</strong><p>${bad.slice(0,4).map(x=>`Row ${x.row}: ${x.missing.join(', ')}`).join('<br>')}</p></div>`;}); }
  function adminGuarantee(){ const s=Store.get(),t=E.getTrack(s.user.selectedTrackId);return `<div class="page"><div class="page-head"><div><span class="eyebrow">Guarantee operations</span><h1>Rules and cases</h1><p>Track duration, daily commitment and spaced repetition all constrain the live guarantee. Refund/payment execution is not automated in V1.</p></div></div><div class="table-wrap"><table><thead><tr><th>Track</th><th>Days</th><th>Daily</th><th>Guaranteed minimum</th><th>Realistic target</th><th>400 probability</th></tr></thead><tbody>${D.tracks.map(x=>`<tr><td>${x.name}</td><td>${x.days}</td><td>${x.hours}h</td><td>${x.guaranteed}/400</td><td>${x.target}</td><td>${x.perfectProb}%</td></tr>`).join('')}</tbody></table></div><div class="callout info" style="margin-top:16px"><strong>Current demo case</strong><p>${s.user.name}: ${t.name} selected, live guarantee ${s.score.guaranteed}/400, rolling compliance ${s.compliance.rollingAverage}%.</p></div><div class="section-title"><h2>Financial eligibility states</h2></div><div class="grid two"><div class="card flat"><strong>Misses minimum, 80%+ compliance</strong><p>Eligible for one full free track extension, same duration and subjects.</p></div><div class="card flat"><strong>Extension also fails, compliance maintained</strong><p>Eligible for 50% refund within 30 days, subject to reviewed contract terms.</p></div><div class="card flat"><strong>Below 80% compliance</strong><p>Guarantee voided, no extension or refund.</p></div><div class="card flat"><strong>Missed exam sitting after completion</strong><p>Extension held, access remains available for light revision until the next sitting.</p></div></div></div>`; }
  function adminPredictive(){ const s=Store.get();return `<div class="page"><div class="page-head"><div><span class="eyebrow">Predictive data model</span><h1>Early-warning rules</h1><p>V1 starts with explainable rules. Event history is structured so future statistical models can be calibrated on real outcomes.</p></div></div><div class="grid">${s.admin.predictiveRules.map(r=>`<div class="card flat"><div class="progress-row"><div><strong>${esc(r.label)}</strong><p>Response: ${esc(r.response)}</p></div><button class="switch ${r.enabled?'on':''}" data-rule="${r.id}"></button></div></div>`).join('')}</div></div>`; }
  function bindPredictive(){ $$('[data-rule]').forEach(b=>b.onclick=()=>{Store.patch(s=>{const r=s.admin.predictiveRules.find(x=>x.id===b.dataset.rule);r.enabled=!r.enabled;s.admin.audit.unshift({date:new Date().toISOString(),actor:'Admin',action:`${r.enabled?'Enabled':'Disabled'} predictive rule: ${r.label}`});});render();}); }
  function adminValidation(){ const s=Store.get();const outs=s.postExamOutcomes;const avg=outs.length?Math.round(outs.reduce((a,x)=>a+x.error,0)/outs.length):null;return `<div class="page"><div class="page-head"><div><span class="eyebrow">Post-exam validation</span><h1>Actual vs predicted results</h1><p>This database exists from day 1 even when empty. It is the feedback loop for recalibrating Power Topics, mocks and score projections.</p></div></div><div class="grid three"><div class="metric"><div class="metric-label">Submitted outcomes</div><div class="metric-value">${outs.length}</div></div><div class="metric"><div class="metric-label">Mean model error</div><div class="metric-value">${avg==null?'—':`${avg>0?'+':''}${avg}`}</div></div><div class="metric"><div class="metric-label">Model version</div><div class="metric-value" style="font-size:1.1rem">${esc(s.score.modelVersion)}</div></div></div>${outs.length?`<div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Date</th><th>Predicted</th><th>Actual</th><th>Error</th><th>Compliance</th></tr></thead><tbody>${outs.map(o=>`<tr><td>${fmtDate(o.date)}</td><td>${o.predictedScore}</td><td>${o.actualScore}</td><td>${o.error>0?'+':''}${o.error}</td><td>${o.compliance}%</td></tr>`).join('')}</tbody></table></div>`:'<div class="callout info" style="margin-top:18px"><strong>Dataset is empty</strong><p>This is expected before users complete real exams. The data structure is already in place.</p></div>'}</div>`; }
  function adminLaunch(){ const s=Store.get();const rows=[['legalReviewComplete','Nigerian consumer protection lawyer review','All guarantee language and financial terms reviewed before public launch'],['coachesStaffed','Learning coaches recruited and trained','Trained coaches available on day 1']];return `<div class="page"><div class="page-head"><div><span class="eyebrow">Private launch readiness</span><h1>Pre-launch conditions</h1><p>These are preconditions, not optional features. NeuroPass should not be represented as legally launch-ready until both manual blockers are complete.</p></div>${status(s.admin.legalReviewComplete&&s.admin.coachesStaffed?'Ready for final release review':'Blocked',s.admin.legalReviewComplete&&s.admin.coachesStaffed?'success':'danger')}</div><div class="grid">${rows.map(([k,t,d])=>`<div class="card"><div class="progress-row"><div><h3>${t}</h3><p>${d}</p></div><button class="switch ${s.admin[k]?'on':''}" data-readiness="${k}"></button></div>${status(s.admin[k]?'Manually confirmed':'Unresolved',s.admin[k]?'success':'danger')}</div>`).join('')}</div><div class="section-title"><h2>Required build checks</h2></div><div class="grid two">${Object.entries(s.admin.checks).map(([k,v])=>`<div class="card flat"><div class="progress-row"><strong>${({offlineMode:'Offline mode',dyslexiaUI:'Dyslexia-first UI',rollingCompliance:'Rolling compliance',cfaExcluded:'CFA excluded from V1',postExamArchitecture:'Post-exam validation architecture'})[k]}</strong>${status(v?'Built':'Missing',v?'success':'danger')}</div></div>`).join('')}</div></div>`; }
  function bindLaunch(){ $$('[data-readiness]').forEach(b=>b.onclick=()=>{const k=b.dataset.readiness;Store.patch(s=>{s.admin[k]=!s.admin[k];s.admin.audit.unshift({date:new Date().toISOString(),actor:'Admin',action:`Launch precondition ${k}: ${s.admin[k]?'confirmed':'reopened'}`});});render();}); }

  function viewFor(r){
    const role=Store.get().currentRole;
    if(r==='study-session')return studySessionView();if(r==='mock-live')return mockLive();
    if(role==='student')return ({home,study:studyPage,practice:practicePage,mocks:mocksPage,'mistake-bank':mistakePage,progress:progressPage,coach:coachPage,settings:settingsPage,'parent-share':parentShare,'cfa-coming-soon':cfaPage}[r]||home)();
    if(role==='admin')return ({admin:adminOverview,'admin-content':adminContent,'admin-import':adminImport,'admin-guarantee':adminGuarantee,'admin-predictive':adminPredictive,'admin-validation':adminValidation,'admin-launch':adminLaunch,settings:settingsPage}[r]||adminOverview)();
    return ({'coach-dashboard':coachDashboard,'risk-queue':riskQueue,'assigned-students':assignedStudents,'coach-inbox':coachInbox,settings:settingsPage}[r]||coachDashboard)();
  }

  function bindFor(r){
    bindShell();
    if(r==='home')bindHome();if(r==='study')bindStudy();if(r==='study-session')bindStudySession();if(r==='practice')bindPractice();if(r==='mocks')bindMocks();if(r==='mock-live')bindMockLive();if(r==='mistake-bank')bindMistakes();if(r==='progress')bindProgress();if(r==='coach'||r==='coach-inbox')bindCoach();if(r==='parent-share')bindParentShare();if(r==='settings')bindSettings();if(r==='cfa-coming-soon')bindCfa();if(r==='coach-dashboard')bindCoachDashboard();if(r==='risk-queue')bindRiskQueue();if(r==='admin-import')bindAdminImport();if(r==='admin-predictive')bindPredictive();if(r==='admin-launch')bindLaunch();
  }

  function recalc(){
    const s=Store.get(),avg=E.avgHoursFromState(s),last=s.mockHistory.at(-1);const calc=E.projectGuarantee({daysElapsed:s.user.currentDay,avgDailyHours:avg,compliance:s.compliance.rollingAverage,mockScore:last?.score,baseline:s.user.baselineScore,selectedTrackId:s.user.selectedTrackId});
    // Preserve a realistic seeded demo when model inputs are synthetic, then update after interactions.
    if((s.answers?.length||0)>0 || (s.mockHistory?.length||0)>4){Store.patch(x=>{x.score.guaranteed=calc.guaranteed;x.score.projected=calc.projected;x.score.modelVersion=calc.modelVersion;x.score.updatedAt=new Date().toISOString();});}
  }

  function render(){
    cleanupTransient();applySettings();const s=Store.get();if(!s.authenticated)return authView();const r=route();if(r==='study-session'&&studyCtx){} else if(r!=='study-session')sessionSeconds=0;
    const validStudent=['home','study','study-session','practice','mocks','mock-live','mistake-bank','progress','coach','settings','parent-share','cfa-coming-soon'];
    if(s.currentRole!=='student' && ['study-session','mock-live','parent-share'].includes(r)){go(s.currentRole==='admin'?'admin':'coach-dashboard');return;}
    $('#app').innerHTML=shell(viewFor(r),r);bindFor(r);if(r==='study-session')ensureTimer();
  }

  function network(){ const b=$('#offlineBanner');if(b)b.classList.toggle('hidden',navigator.onLine);if(navigator.onLine)Store.flushQueue(); }
  window.addEventListener('hashchange',render);window.addEventListener('online',()=>{network();toast('Back online. Pending progress is syncing.');render();});window.addEventListener('offline',()=>{network();toast('Offline mode active. Downloaded study content still works.');render();});
  if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>{});
  async function bootstrap(){
    network();
    if(window.NPSupabase){
      const {data:{session}}=await window.NPSupabase.auth.getSession();
      if(session?.user){
        await loadAuthenticatedUser(session.user);
      } else if(!Store.get().demoMode){
        Store.patch(s=>{s.authenticated=false;s.currentRole='student';});
      }
      window.NPSupabase.auth.onAuthStateChange((event,session)=>{
        if(event==='SIGNED_OUT'){
          Store.detachRemoteUser();
          Store.patch(s=>{s.authenticated=false;s.demoMode=false;s.currentRole='student';});
          render();
        }
      });
    }
    recalc();render();
  }
  bootstrap();
})();
